  Lemma m0_fs : m_fs model0 = fs0.
Proof.
ltac2:(KReplay.run1 (kr_t_O23Open ()) ["Open"] "p;2g007Dj20Tg002Qp,3fs0'0o"). Qed.
  Lemma m0_pure : md_pure model0.
Proof.
