       realizes RSEGS (mkCfg (mkst (regupd R 10 (alloc_fd (m_fds model0))) (v_addi (Z_to_bv 64 0x10ab4c) 4) M (seg_rom RSEGS))
                            (with_fds (fd_insert (m_fds model0) (alloc_fd (m_fds model0)) fd3) model0)) KB ->
       realizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0x10ab4c) M (seg_rom RSEGS)) model0) (t_alt2 KA KB)) ->
    open_err_branch KA -> at_malloc fd3 KB ->
    realizes RSEGS (mkCfg (mkst regs0 (Z_to_bv 64 0x62b1c) mem0 (seg_rom RSEGS)) model0) (t_alt2 KA KB).
