  Theorem open_file_pipeline : forall fdata KA KB,
    fs_lookup fs0 path = Some fdata -> path <> [] -> path <> dot_path -> (length path <= 4095)%nat ->
    open_err_branch KA -> at_malloc (FdFile path (Z_to_bv 64 0)) KB ->
